mapper.insert:
INSERT INTO diary_covers (
    diary_id, base_cover_style, background_color, created_at, updated_at
) VALUES (
    #{diaryId}, #{baseCoverStyle}, #{backgroundColor}, NOW(), NOW()
)

mapper.update:
UPDATE diary_covers c
JOIN diaries d ON d.id = c.diary_id
SET c.base_cover_style = #{cover.baseCoverStyle},
    c.background_color = #{cover.backgroundColor},
    c.updated_at = NOW()
WHERE c.id = #{cover.id}
  AND c.diary_id = #{cover.diaryId}
  AND d.user_id = #{userId}

mapper.delete:
DELETE c FROM diary_covers c
JOIN diaries d ON d.id = c.diary_id
WHERE c.diary_id = #{diaryId}
  AND d.user_id = #{userId}
